import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

max_reduce_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor max_reduce_dim(torch::Tensor x, int64_t dim);
"""

max_reduce_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

__global__ void max_reduce_dim_kernel(
    const float* __restrict__ X,
    float* __restrict__ Y,
    int outer,
    int R,
    int inner,
    int64_t total)
{
  // CUTE views of the contiguous input/output as (outer, R, inner) -> (outer, inner)
  Tensor mX = make_tensor(
      make_gmem_ptr(X),
      make_shape(outer, R, inner),
      make_stride((int64_t)R * inner, (int64_t)inner, Int<1>{})
  );

  Tensor mY = make_tensor(
      make_gmem_ptr(Y),
      make_shape(outer, inner),
      make_stride((int64_t)inner, Int<1>{})
  );

  const int64_t tid = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  const int64_t step = (int64_t)gridDim.x * blockDim.x;

  for (int64_t idx = tid; idx < total; idx += step) {
    const int64_t o = idx / inner;
    const int64_t i = idx - o * inner;

    float acc = mX(o, 0, i);
    #pragma unroll 4
    for (int r = 1; r < R; ++r) {
      acc = fmaxf(acc, mX(o, r, i));
    }
    mY(o, i) = acc;
  }
}

torch::Tensor max_reduce_dim(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  const int64_t rank = x.dim();
  TORCH_CHECK(rank >= 1, "x must have at least 1 dimension");

  int64_t d = dim;
  if (d < 0) d += rank;
  TORCH_CHECK(d >= 0 && d < rank, "dim out of range");

  auto xc = x.contiguous();

  int64_t outer = 1;
  for (int64_t i = 0; i < d; ++i) outer *= xc.size(i);
  const int64_t R = xc.size(d);
  TORCH_CHECK(R > 0, "reduction dimension must be non-empty");
  int64_t inner = 1;
  for (int64_t i = d + 1; i < rank; ++i) inner *= xc.size(i);

  std::vector<int64_t> out_sizes;
  out_sizes.reserve(rank - 1);
  for (int64_t i = 0; i < rank; ++i) {
    if (i != d) out_sizes.push_back(xc.size(i));
  }

  auto y = torch::empty(out_sizes, xc.options());
  const int64_t total = outer * inner;
  if (total == 0) return y;

  TORCH_CHECK(outer <= INT32_MAX && R <= INT32_MAX && inner <= INT32_MAX,
              "reduction extents too large for this kernel");

  const int threads = 256;
  int64_t blocks = (total + threads - 1) / threads;
  if (blocks < 1) blocks = 1;
  if (blocks > 2147483647LL) blocks = 2147483647LL;

  dim3 block((unsigned)threads);
  dim3 grid((unsigned)blocks);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  max_reduce_dim_kernel<<<grid, block, 0, stream>>>(
      xc.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)outer,
      (int)R,
      (int)inner,
      total
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "max_reduce_dim_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

max_reduce_ext = load_inline(
    name="cute_max_reduce_dim_ext",
    cpp_sources=max_reduce_cpp_decl,
    cuda_sources=max_reduce_cuda_src,
    functions=["max_reduce_dim"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Max reduction over a specific dimension using a single custom CUTE/CUDA kernel.
    For the provided case (dim=1 on [B, M, N]), this reduces over M while keeping
    coalesced accesses across the contiguous N dimension.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = int(dim)
        self._ext = max_reduce_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.max_reduce_dim(x, self.dim)

